  ('profile', 'ali', 0, true, '{"id":"ali","name":"علی فرقانی","brand":"ALDMC","role":"طراح محصول، UI/UX و مدرس","studioLine":"برای ایده‌هایی که باید واقعی بشن.","bio":"از طراحی رابط توی فیگما تا ساخت نمونه‌ی تعاملی و بررسی کیفیت اجرا، همراه پروژه می‌مونم. تمرکزم روی وب فارسی، تجربه‌ی کاربری و تولید خلاقانه با هوش مصنوعیه.","contact":[{"label":"ایمیل","href":"mailto:aldmc4543@gmail.com"},{"label":"تلگرام","href":"https://t.me/ALDMC"},{"label":"واتس‌اپ","href":"https://wa.me/989174543813"},{"label":"Instagram","href":"https://www.instagram.com/aldmc_origin/"},{"label":"GitHub","href":"https://github.com/ALDMC3215"}]}'::jsonb),
  ('projects', 'nader-gold', 0, true, '{"id":"nader-gold","title":"فروشگاه آنلاین نادرگلد (Nader Gold)","category":"product","label":"E-commerce · Luxury jewelry","role":"طراح محصول و تجربه خرید دیجیتال","summary":"طراحی دموی فروشگاه طلا و جواهر بر پایه موتیف‌های اصیل ایرانی، قیمت‌گذاری زنده طلا و ارز، طراحی اول-موبایل (Mobile-First) و سبد خرید روان.","tags":["MOBILE-FIRST","LUXURY UI","GOLD PRICING API"],"kind":"Demo","order":0,"art":"/projects/retro-nader.webp","short":"نادرگلد"}'::jsonb),
  ('projects', 'picofy-landing', 1, true, '{"id":"picofy-landing","title":"لندینگ تعاملی پیکوفای (Picofy)","category":"web","label":"Web 3D · Telegram services","role":"طراح هویت بصری، وب و تعاملات سه‌بعدی","summary":"طراحی و پیاده‌سازی لندینگ خدمات تلگرام با صحنه تعاملی سه‌بعدی Three.js، زبان بصری های‌تک در تم تیره، شیدرهای شیشه‌ای و نرخ تبدیل بهینه.","tags":["THREE.JS","WEBGL","FIGMA","MICRO-INTERACTIONS"],"link":"https://picofy.com","image":"/projects/picofy-live.webp","order":1,"art":"/projects/retro-picofy.webp","short":"پیکوفای"}'::jsonb),
  ('projects', 'call-manager', 2, true, '{"id":"call-manager","title":"سامانه مدیریت تماس نوین‌تک (Call Manager)","category":"product","label":"Internal CRM · Workflow","role":"طراح سیستم مدیریت اطلاعات و داشبورد","summary":"طراحی سیستم داخلی ثبت و پیگیری مراجعین و تماس‌های موسسه خبره‌بنیان در کمتر از ۳۰ ثانیه با ساختار استاندارد فارسی و داشبورد گزارش‌گیری.","tags":["INTERNAL CRM","RTL DASHBOARD","RAPID LOGGING"],"image":"/projects/call-manager-live.webp","kind":"Internal","order":2,"art":"/projects/retro-novin.webp","short":"مدیریت تماس نوین‌تک"}'::jsonb),
  ('projects', 'shiraz-portal', 3, true, '{"id":"shiraz-portal","title":"صفحه اصلی پورتال شهرداری شیراز","category":"web","label":"Portal · Public sector","role":"طراح ارشد رابط و تجربه کاربری (UI/UX)","summary":"طراحی جامع تجربه و رابط کاربری صفحه اول وبسایت شهرداری شیراز.","extra":"معماری خدمات شهروندی الکترونیک، سامانه‌های یکپارچه شهری و دسترسی‌پذیری برای بیش از ۲ میلیون شهروند.","tags":["SHIRAZ.IR","UI/UX ARCHITECTURE","FIGMA","DESIGN SYSTEM"],"link":"https://shiraz.ir","order":10}'::jsonb),
  ('projects', 'habisa-ai', 4, true, '{"id":"habisa-ai","title":"مجموعه ویدیویی و داستانی هابیسا (Habisa)","category":"ai","label":"AI video · Generative production","role":"سناریونویس و کارگردان فنی هوش مصنوعی","summary":"ابداع زبان بصری مقوایی با ابزارهای Google Flow و Veo، سناریونویسی و تولید محتوای تبلیغاتی هوش مصنوعی در حوزه صنعت ساختمان و املاک.","tags":["GOOGLE VEO","GOOGLE FLOW","STORYBOARDING","MIDJOURNEY"],"image":"/projects/habisa-poster.jpg","order":14}'::jsonb),
  ('projects', 'content-novintech', 5, true, '{"id":"content-novintech","title":"طراحی محتوای دیجیتال و هویت بصری نوین‌تک","category":"brand","label":"Visual systems · Social media","role":"طراحی محتوا و هدایت هویت بصری","summary":"طراحی و توسعه سیستم‌های محتوایی، قالب‌های آموزشی و تبلیغاتی و حفظ یکپارچگی هویت بصری در شبکه‌های اجتماعی.","extra":"طراحی گریدبندی اختصاصی اسلایدها و استوری‌های آموزشی فارسی؛ هماهنگی پالت رنگی سازمانی با تایپوگرافی خوانا و مدرن؛ تدوین راهنمای بصری برای تولید مداوم و باکیفیت محتوا.","tags":["VISUAL SYSTEMS","SOCIAL MEDIA","EDUCATION"],"image":"/social/novintech/novintech-post-1.jpg","order":15}'::jsonb),
  ('projects', 'content-picofy', 6, true, '{"id":"content-picofy","title":"طراحی محتوای تکنولوژی و شبکه‌های اجتماعی پیکوفای","category":"brand","label":"AI tech content · Brand","role":"طراحی محتوا و هدایت هویت بصری","summary":"طراحی و مدیریت محتوای بصری، توسعه قالب‌های خبری و تبلیغاتی و ایجاد زبان بصری یکپارچه برای محصولات و خدمات دیجیتال.","extra":"طراحی پست‌های تکنولوژی‌محور و کاورهای گرافیکی مقایسه‌ای هوش مصنوعی؛ زبان طراحی تیره با کنتراست رنگی نئونی؛ مدیریت پیج و تعامل با جامعه کاربری حوزه فناوری.","tags":["CONTENT DESIGN","DARK THEME","AI TECH"],"link":"https://www.instagram.com/picofy_ir/","image":"/social/picofy/picofy-sample-2-claude-chatgpt.jpg","order":16}'::jsonb),
  ('projects', 'aldmc-design-system', 7, true, '{"id":"aldmc-design-system","title":"سیستم جامع طراحی و دیزاین سیستم ALDMC","category":"brand","label":"Design System · Persimmon V6","role":"معمار دیزاین سیستم و طراح ارشد هویت بصری","summary":"معماری و تدوین جامع دیزاین سیستم برند شخصی ALDMC در دو حالت تیره (#27211D Charcoal) و روشن (#F6F0E7 Paper)؛ با پالت اختصاصی رنگ خرمالویی (Persimmon #E76338)، تایپوگرافی دوزبانه و کتابخانه کامل کامپوننت‌های تعاملی UI.","extra":"تدوین اتم‌ها، مولکول‌ها و ارگانیسم‌های UI در فیگما؛ شامل دکمه‌ها، فیلدهای ورودی، منوها، کارت‌ها، فیلترها و کامپوننت‌های رسانه‌ای با رعایت کامل کنتراست دسترسی‌پذیری WCAG AAA و گریدبندی واکنش‌گرا.","tags":["DESIGN SYSTEM","PERSIMMON V6","FIGMA","UI TOKENS","WCAG AAA"],"image":"/brand/design-system/components-dark.svg","order":17}'::jsonb),
  ('projects', 'aldmc-brand', 8, true, '{"id":"aldmc-brand","title":"هویت بصری ALDMC (نسخه ۶ خرمالویی)","category":"brand","label":"Brand identity · Persimmon V6","role":"طراحی خلاق، هویت بصری و Vibe Coding","summary":"خلق هویت بصری جامع نسخه ۶ خرمالویی، توسعه وب با متد Vibe Coding و Agentic AI، ساخت کامپوننت‌های تعاملی و موسیقی با هوش مصنوعی.","tags":["BRAND IDENTITY","VIBE CODING","AI MEDIA PRODUCTION"],"image":"/brand/mockups/04-stationery-brand-system.webp","order":18}'::jsonb),
