create table if not exists public.portfolio_entries (
  section text not null check (section in ('profile', 'projects', 'experience', 'services', 'music')),
  slug text not null check (length(slug) between 1 and 100),
  position integer not null check (position >= 0),
  published boolean not null default false,
  content jsonb not null check (jsonb_typeof(content) = 'object' and content ->> 'id' = slug),
  primary key (section, slug)
);
alter table public.portfolio_entries enable row level security;
revoke all on public.portfolio_entries from anon, authenticated;
grant select on public.portfolio_entries to anon, authenticated;
create policy "Published portfolio content is readable" on public.portfolio_entries
  for select to anon, authenticated using (published);
create index portfolio_entries_published_order_idx
  on public.portfolio_entries (position, slug) where published;
on conflict (section, slug) do nothing;
